        return socket.socket(socket.AF_INET, socket.SOCK_DGRAM, proto)
    else:
        proto = socket.IPPROTO_ICMPV6
        if privileged:
            return socket.socket(socket.AF_INET6, socket.SOCK_RAW, proto)
        return socket.socket(socket.AF_INET6, socket.SOCK_DGRAM, proto)


