    if not (privileged and transmitted == 0 and received == 0 and run_error and run_error.startswith("listen ")):
        format_summary(host, transmitted, received, rtts)
    if run_error:
        eprint_error(f"an error occurred when running ping: {run_error}")
        return 2
    return 0


def main(argv: List[str]) -> int:
    opts, perr = parse_args(argv)
    if perr is not None:
        sys.stderr.write(perr + "\n")
        eprint_error("parse error: " + perr)
        return 1
    assert opts is not None
    if opts.help:
        sys.stdout.write(HELP + "\n")
        return 0
    if opts.version:
        sys.stdout.write(VERSION + "\n")
        return 0
    if len(opts.positionals) == 0:
        eprint_error("must requires an argument")
        return 1
    if len(opts.positionals) > 1:
        eprint_error("too many arguments")
        return 1
    host = opts.positionals[0]
    try:
        ip, fam = resolve_host(host)
    except RuntimeError as e:
        eprint_error("an error occurred while initializing pinger: " + str(e))
        return 0
    format_header(host, ip)
    return running_ping(host, ip, fam, opts.count, opts.privilege)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(1)
