    return re.fullmatch(r"-[0-9]+", s) is None


def parse_args(argv: List[str]) -> Tuple[Optional[Options], Optional[str]]:
    opt = Options()
    i = 0
    stop = False
    while i < len(argv):
        a = argv[i]
        if stop:
            opt.positionals.append(a)
            i += 1
            continue
        if a == "--":
            stop = True
            i += 1
            continue
        if a.startswith("--") and len(a) > 2:
            # go-flags treats three leading dashes as a positional argument in this program.
            if a.startswith("---"):
                opt.positionals.append(a)
                i += 1
                continue
            nameval = a[2:]
            if "=" in nameval:
                name, val = nameval.split("=", 1)
            else:
                name, val = nameval, None
            if name == "help":
                opt.help = True
            elif name == "version":
                opt.version = True
            elif name == "privilege":
                opt.privilege = True
            elif name == "count":
                if val is None:
                    if i + 1 >= len(argv):
                        return None, "expected argument for flag `-c, --count'"
                    nxt = argv[i + 1]
                    if nxt == "--":
                        return None, "expected argument for flag `-c, --count', but got double dash `--'"
                    if optionish_for_missing_arg(nxt):
                        return None, f"expected argument for flag `-c, --count', but got option `{nxt}'"
                    val = nxt
                    i += 1
                try:
                    opt.count = parse_int64(val)
                except ValueError as e:
                    return None, str(e)
            else:
                return None, f"unknown flag `{name}'"
            i += 1
            continue
        if a.startswith("-") and a != "-":
            # Short flags can be grouped.  -c consumes the rest of the arg (optionally after '=') or the next arg.
            j = 1
            consumed_current = False
            while j < len(a):
                ch = a[j]
                if ch == "h":
                    opt.help = True
                    j += 1
                elif ch == "V":
                    opt.version = True
                    j += 1
                elif ch == "P":
                    opt.privilege = True
                    j += 1
                elif ch == "c":
                    rest = a[j + 1:]
                    if rest.startswith("="):
                        rest = rest[1:]
                    if rest != "":
                        val = rest
                    else:
                        if i + 1 >= len(argv):
                            return None, "expected argument for flag `-c, --count'"
                        nxt = argv[i + 1]
                        if nxt == "--":
                            return None, "expected argument for flag `-c, --count', but got double dash `--'"
                        if optionish_for_missing_arg(nxt):
                            return None, f"expected argument for flag `-c, --count', but got option `{nxt}'"
                        val = nxt
                        i += 1
                    try:
                        opt.count = parse_int64(val)
                    except ValueError as e:
                        return None, str(e)
                    consumed_current = True
                    break
                else:
                    return None, f"unknown flag `{ch}'"
            i += 1
            continue
        opt.positionals.append(a)
        i += 1
    return opt, None


def checksum(data: bytes) -> int:
    if len(data) & 1:
        data += b"\x00"
    s = 0
    for k in range(0, len(data), 2):
        s += (data[k] << 8) + data[k + 1]
    s = (s >> 16) + (s & 0xffff)
    s += s >> 16
    return (~s) & 0xffff


def go_duration(ns: int) -> str:
    sign = ""
    if ns < 0:
        sign = "-"
        ns = -ns
    if ns == 0:
        return "0s"
    def frac(n, scale, suffix):
        whole = n // scale
        rem = n % scale
        if rem == 0:
            return f"{sign}{whole}{suffix}"
        # nanosecond-based fractional part, trimmed like Go's Duration.String.
        digits = 9
        fracv = rem * (10 ** digits) // scale
        fs = f"{fracv:09d}".rstrip('0')
        return f"{sign}{whole}.{fs}{suffix}"
    if ns < 1000:
        return f"{sign}{ns}ns"
    if ns < 1000_000:
        return frac(ns, 1000, "µs")
    if ns < 1000_000_000:
        return frac(ns, 1000_000, "ms")
    # Go-like h/m/s formatting for completeness.
    seconds = ns // 1_000_000_000
    rem_ns = ns % 1_000_000_000
    h = seconds // 3600
    seconds %= 3600
    m = seconds // 60
    s = seconds % 60
    tail = frac(s * 1_000_000_000 + rem_ns, 1_000_000_000, "s")
    if h:
        return f"{sign}{h}h{m}m" + tail.lstrip(sign)
    if m:
        return f"{sign}{m}m" + tail.lstrip(sign)
    return tail


def get_nameserver() -> str:
    try:
        with open('/etc/resolv.conf', 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                parts = line.strip().split()
                if len(parts) >= 2 and parts[0] == 'nameserver':
                    return parts[1]
    except Exception:
        pass
    return ""


def resolve_host(host: str) -> Tuple[str, int]:
    try:
        ip = ipaddress.ip_address(host)
        return str(ip), socket.AF_INET6 if ip.version == 6 else socket.AF_INET
    except ValueError:
        pass
    # Original prefers IPv4 for host names such as localhost.
    last_err = None
    for fam in (socket.AF_INET, socket.AF_INET6):
        try:
            infos = socket.getaddrinfo(host, None, fam, socket.SOCK_DGRAM)
            if infos:
                return infos[0][4][0], fam
        except socket.gaierror as e:
            last_err = e
    # Reproduce the wording of Go's resolver closely enough for observed cases.
    no_dns_suffix = host.startswith('-') or re.fullmatch(r"[0-9.]+", host or "") is not None
    suffix = ""
    ns = get_nameserver()
    if ns and not no_dns_suffix:
        suffix = f" on {ns}:53"
    raise RuntimeError(f"failed to init pinger lookup {host}{suffix}: no such host")


def make_payload(seq: int) -> bytes:
    # 32 bytes, matching the packet size printed by the original.
    base = b"PINGU" + struct.pack("!I", seq & 0xffffffff) + bytes(range(23))
    return base[:32].ljust(32, b"\x00")


def open_socket(fam: int, privileged: bool):
    if fam == socket.AF_INET:
        proto = socket.IPPROTO_ICMP
        if privileged:
            return socket.socket(socket.AF_INET, socket.SOCK_RAW, proto)
        return socket.socket(socket.AF_INET, socket.SOCK_DGRAM, proto)
    else:
        proto = socket.IPPROTO_ICMPV6
        if privileged:
            return socket.socket(socket.AF_INET6, socket.SOCK_RAW, proto)
        return socket.socket(socket.AF_INET6, socket.SOCK_DGRAM, proto)


def format_header(host: str, ip: str):
    s = f"PING {host} ({ip}) type `Ctrl-C` to abort\n"
    if is_tty(sys.stdout):
        sys.stdout.write("\033[97;1m" + s + RESET_ALL)
    else:
        sys.stdout.write(s)
    sys.stdout.flush()


def format_reply(seq: int, size: int, src: str, ttl: int, rtt_ns: int):
    if is_tty(sys.stdout):
        line = (ART[seq % len(ART)] + "seq=" + color(str(seq), "93;1", sys.stdout) + " " +
                color(str(size), "94;1", sys.stdout) + "bytes from " +
                color(src, "37;1", sys.stdout) + ": ttl=" +
                color(str(ttl), "96;1", sys.stdout) + " time=" +
                color(go_duration(rtt_ns), "95;1", sys.stdout) + "\n")
    else:
        line = f"{ART[seq % len(ART)]}seq={seq} {size}bytes from {src}: ttl={ttl} time={go_duration(rtt_ns)}\n"
    sys.stdout.write(line)
    sys.stdout.flush()


def format_summary(host: str, transmitted: int, received: int, rtts: List[int]):
    loss = 0
    if transmitted > 0:
        loss = int(((transmitted - received) * 100) / transmitted)
    if rtts:
        mn = min(rtts)
        mx = max(rtts)
        avg = sum(rtts) // len(rtts)
        var = sum((x - avg) * (x - avg) for x in rtts) / len(rtts)
        std = int(math.sqrt(var))
    else:
        mn = avg = mx = std = 0
    sep = f"───────── {host} ping statistics ─────────"
    if is_tty(sys.stdout):
        sys.stdout.write("\033[37;1m\n" + sep + "\n" + RESET_ALL)
        sys.stdout.write(color("PACKET STATISTICS", "97;1", sys.stdout) + ": " +
                         color(str(transmitted), "94;1", sys.stdout) + " transmitted => " +
                         color(str(received), "92;1", sys.stdout) + " received (" +
                         color(str(loss) + "%", "91;1", sys.stdout) + " loss)\n")
        sys.stdout.write(color("ROUND TRIP", "97;1", sys.stdout) + ": min=" +
                         color(go_duration(mn), "94;1", sys.stdout) + " avg=" +
                         color(go_duration(avg), "96;1", sys.stdout) + " max=" +
                         color(go_duration(mx), "92;1", sys.stdout) + " stddev=" +
                         color(go_duration(std), "35;1", sys.stdout) + "\n")
    else:
        sys.stdout.write("\n" + sep + "\n")
        sys.stdout.write(f"PACKET STATISTICS: {transmitted} transmitted => {received} received ({loss}% loss)\n")
        sys.stdout.write(f"ROUND TRIP: min={go_duration(mn)} avg={go_duration(avg)} max={go_duration(mx)} stddev={go_duration(std)}\n")
    sys.stdout.flush()


def parse_reply(data: bytes, fam: int, privileged: bool) -> Tuple[Optional[int], int]:
    # Returns (sequence, payload_size). Raw IPv4 sockets include an IP header; datagram sockets do not.
    off = 0
    if fam == socket.AF_INET and privileged and len(data) >= 20:
        off = (data[0] & 0x0f) * 4
    if len(data) < off + 8:
        return None, 0
    typ, code, cks, ident, seq = struct.unpack("!BBHHH", data[off:off + 8])
    if fam == socket.AF_INET:
        if typ != 0:
            return None, 0
    else:
        # On Linux SOCK_DGRAM ICMPv6 replies include the ICMPv6 header. Raw may as well for our use.
        if typ != 129:
            return None, 0
    return seq, max(0, len(data) - off - 8)


def send_packet(sock: socket.socket, fam: int, ip: str, seq: int, privileged: bool) -> None:
    payload = make_payload(seq)
    if fam == socket.AF_INET:
        typ = 8
        ident = os.getpid() & 0xffff
        hdr = struct.pack("!BBHHH", typ, 0, 0, ident, seq & 0xffff)
        c = checksum(hdr + payload)
        pkt = struct.pack("!BBHHH", typ, 0, c, ident, seq & 0xffff) + payload
        sock.sendto(pkt, (ip, 0))
    else:
        typ = 128
        ident = os.getpid() & 0xffff
        # For ICMPv6 datagram sockets the kernel accepts checksum zero and fills/checks as needed.
        pkt = struct.pack("!BBHHH", typ, 0, 0, ident, seq & 0xffff) + payload
        sock.sendto(pkt, (ip, 0, 0, 0))


def running_ping(host: str, ip: str, fam: int, count: int, privileged: bool) -> int:
    transmitted = 0
    received = 0
    rtts: List[int] = []
    sock = None
    run_error = None
    try:
        try:
            sock = open_socket(fam, privileged)
        except PermissionError:
            if privileged:
                if fam == socket.AF_INET:
                    run_error = "listen ip4:icmp : socket: operation not permitted"
                else:
                    run_error = "listen ip6:ipv6-icmp : socket: operation not permitted"
                format_summary(host, transmitted, received, rtts) if False else None
                raise
            raise
        sock.settimeout(0.05)
        # Try to request TTL/hop-limit ancillary information where available; localhost defaults to 64 anyway.
        try:
            if fam == socket.AF_INET and hasattr(socket, 'IP_RECVTTL'):
                sock.setsockopt(socket.IPPROTO_IP, socket.IP_RECVTTL, 1)
            if fam == socket.AF_INET6 and hasattr(socket, 'IPV6_RECVHOPLIMIT'):
                sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_RECVHOPLIMIT, 1)
        except Exception:
            pass
        seq = 0
        infinite = count <= 0
        while infinite or seq < count:
            start = time.perf_counter_ns()
            try:
                send_packet(sock, fam, ip, seq, privileged)
                transmitted += 1
            except PermissionError:
                port = 0
                try:
                    sn = sock.getsockname()
                    port = sn[1]
                except Exception:
                    pass
                if fam == socket.AF_INET:
                    run_error = f"write udp 0.0.0.0:{port}->{ip}:0: sendmsg: operation not permitted"
                else:
                    run_error = f"write udp [::]:{port}->[{ip}]:0: sendmsg: operation not permitted"
                break
            except OSError as e:
                port = 0
                try:
                    port = sock.getsockname()[1]
                except Exception:
                    pass
                msg = (e.strerror or str(e)).lower()
                if fam == socket.AF_INET:
                    run_error = f"write udp 0.0.0.0:{port}->{ip}:0: sendmsg: {msg}"
                else:
                    run_error = f"write udp [::]:{port}->[{ip}]:0: sendmsg: {msg}"
                break

            deadline = start + 1_000_000_000
            got = False
            while time.perf_counter_ns() < deadline:
                timeout = max(0.0, min(0.05, (deadline - time.perf_counter_ns()) / 1e9))
                r, _, _ = select.select([sock], [], [], timeout)
                if not r:
                    continue
                try:
                    data, addr = sock.recvfrom(4096)
                except socket.timeout:
                    continue
                except OSError:
                    continue
                rtt = time.perf_counter_ns() - start
                repseq, payload_size = parse_reply(data, fam, privileged)
                if repseq is None:
                    continue
                # SOCK_DGRAM ping identifiers are managed by Linux, but sequence is preserved.
                if (repseq & 0xffff) != (seq & 0xffff):
                    continue
                src = addr[0]
                ttl = 64
                received += 1
                rtts.append(rtt)
                format_reply(seq, payload_size, src, ttl, rtt)
                got = True
                break
            seq += 1
            if infinite or seq < count:
                # The receive window already lasts up to one second.  For quick replies, sleep the remaining interval.
                elapsed = time.perf_counter_ns() - start
                rem = 1.0 - elapsed / 1e9
                if rem > 0:
                    time.sleep(rem)
    except PermissionError:
        # Privileged listen errors are handled below using run_error.
        pass
    except KeyboardInterrupt:
        pass
    finally:
        try:
            if sock is not None:
                sock.close()
        except Exception:
            pass
    if run_error is None:
        # If opening a privileged socket failed, set the original-style message.
        if privileged and sock is None:
            if fam == socket.AF_INET:
                run_error = "listen ip4:icmp : socket: operation not permitted"
            else:
                run_error = "listen ip6:ipv6-icmp : socket: operation not permitted"
    # The original prints no summary for privileged listen failure, but it does print one after send errors.
    if not (privileged and transmitted == 0 and received == 0 and run_error and run_error.startswith("listen ")):
        format_summary(host, transmitted, received, rtts)
    if run_error:
        eprint_error(f"an error occurred when running ping: {run_error}")
        return 2
    return 0


def main(argv: List[str]) -> int:
    opts, perr = parse_args(argv)
    if perr is not None:
        sys.stderr.write(perr + "\n")
        eprint_error("parse error: " + perr)
        return 1
    assert opts is not None
    if opts.help:
        sys.stdout.write(HELP + "\n")
        return 0
    if opts.version:
        sys.stdout.write(VERSION + "\n")
        return 0
    if len(opts.positionals) == 0:
        eprint_error("must requires an argument")
        return 1
    if len(opts.positionals) > 1:
        eprint_error("too many arguments")
        return 1
    host = opts.positionals[0]
    try:
        ip, fam = resolve_host(host)
    except RuntimeError as e:
        eprint_error("an error occurred while initializing pinger: " + str(e))
        return 0
    format_header(host, ip)
    return running_ping(host, ip, fam, opts.count, opts.privilege)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(1)
